import{_ as a,o as t,c as s,a5 as n}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"Evidence Chain Template","description":"Use one cross-domain worksheet to connect baseline, immediate performance, delayed retention, transfer, and the next decision across English, AI, projects, and life practice.","frontmatter":{"title":"Evidence Chain Template","description":"Use one cross-domain worksheet to connect baseline, immediate performance, delayed retention, transfer, and the next decision across English, AI, projects, and life practice.","updated":"2026-09-01T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/evidence-chain.en.md","name":"evidence-chain.en.md"}},"headers":[],"relativePath":"en/templates/evidence-chain.md","filePath":"en/templates/evidence-chain.md","lastUpdated":1788220800000}'),i={name:"en/templates/evidence-chain.md"};function o(r,e,d,l,h,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="evidence-chain-template" tabindex="-1">Evidence Chain Template <a class="header-anchor" href="#evidence-chain-template" aria-label="Permalink to &quot;Evidence Chain Template&quot;">​</a></h1><p>This worksheet answers one concrete question: <strong>What exactly do I know has changed?</strong></p><p>It does not require every result to improve or turn life into a score. It places samples from the same task under different conditions side by side, so you can distinguish “I can do it now”, “I still can after a few days”, and “I can use it somewhere new”.</p><p>Copy it into a private note and use one copy for each main question. Do not record passwords, identity documents, customer data, medical privacy, or unauthorised third-party information. For health, safety, legal, financial, or persistent loss-of-control concerns, contact a trusted person and a qualified professional first.</p><h2 id="_1-define-the-question" tabindex="-1">1. Define the Question <a class="header-anchor" href="#_1-define-the-question" aria-label="Permalink to &quot;1. Define the Question&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Record start date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation and audience/user:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The one question this record answers:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Possible risks and stop conditions:</span></span></code></pre></div><p>The question should be observable, such as “Can I explain a project risk in English without a script and answer one follow-up?” Do not write “Am I better now?”</p><h2 id="_2-save-an-unaided-baseline" tabindex="-1">2. Save an Unaided Baseline <a class="header-anchor" href="#_2-save-an-unaided-baseline" aria-label="Permalink to &quot;2. Save an Unaided Baseline&quot;">​</a></h2><p>The baseline should happen before AI, peer feedback, or concentrated training whenever possible. Record the conditions so tools, extra time, and familiar material do not disappear from the comparison.</p><table tabindex="0"><thead><tr><th>Date</th><th>Task and constraints</th><th>Tool used?</th><th>Result/errors</th><th>Raw evidence location</th></tr></thead><tbody><tr><td></td><td></td><td>No</td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I could complete independently at baseline:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Where I stopped or needed a prompt:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What the baseline cannot prove:</span></span></code></pre></div><h2 id="_3-record-immediate-performance" tabindex="-1">3. Record Immediate Performance <a class="header-anchor" href="#_3-record-immediate-performance" aria-label="Permalink to &quot;3. Record Immediate Performance&quot;">​</a></h2><p>Immediate performance says what happened under the current conditions. It does not automatically say that ability is stable.</p><table tabindex="0"><thead><tr><th>Date</th><th>Conditions and prompts</th><th>What I completed</th><th>Quality/time/rework</th><th>Evidence location</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>If AI was used, state what it did and what you completed independently after closing it. A chat log is a process trace, not proof of ability by itself.</p><h2 id="_4-test-delayed-retention" tabindex="-1">4. Test Delayed Retention <a class="header-anchor" href="#_4-test-delayed-retention" aria-label="Permalink to &quot;4. Test Delayed Retention&quot;">​</a></h2><p>Wait for a period, remove recent prompts and the original answer, and complete a related task. Choose the interval according to the task and your capacity, but write it down.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Retest date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Time since the last practice:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prompts removed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Related task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Independent result:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Errors that remained:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence location:</span></span></code></pre></div><h2 id="_5-test-transfer" tabindex="-1">5. Test Transfer <a class="header-anchor" href="#_5-test-transfer" aria-label="Permalink to &quot;5. Test Transfer&quot;">​</a></h2><p>Keep the core action and change at least one condition: topic, listener, time limit, material, tool permission, or purpose.</p><table tabindex="0"><thead><tr><th>Changed condition</th><th>New task</th><th>Independent result</th><th>How did the other person/user understand it?</th><th>Evidence location</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>A failed transfer does not make earlier practice worthless. It shows that the change may be too large, prerequisite knowledge is missing, or the acceptance standard needs revision.</p><h2 id="_6-separate-fact-interpretation-and-hypothesis" tabindex="-1">6. Separate Fact, Interpretation, and Hypothesis <a class="header-anchor" href="#_6-separate-fact-interpretation-and-hypothesis" aria-label="Permalink to &quot;6. Separate Fact, Interpretation, and Hypothesis&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fact: I can point to a date, condition, sample, source, or direct observation.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Interpretation: How I understand those facts; it may need revision.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Hypothesis: The judgment I will test in the next action.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Conclusion I cannot draw yet:</span></span></code></pre></div><p>For example, “the unaided version finished in 90 seconds” is a record. “It was clearer because my sleep improved” is an interpretation. “It may work if I can repeat it with an unfamiliar listener next week” is a hypothesis.</p><h2 id="_7-let-evidence-choose-the-next-step" tabindex="-1">7. Let Evidence Choose the Next Step <a class="header-anchor" href="#_7-let-evidence-choose-the-next-step" aria-label="Permalink to &quot;7. Let Evidence Choose the Next Step&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">This evidence most supports: continue / downgrade / change one variable / pause or stop</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The one condition I will change:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance standard for the next task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Support, permission, or professional judgment needed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><p>When evidence conflicts, do not hide the conflict in an average. Write the different conditions first, then decide whether another sample is worth collecting. When evidence is thin, shrinking the question is usually more honest than manufacturing a precise score.</p><h2 id="_8-handover-summary" tabindex="-1">8. Handover Summary <a class="header-anchor" href="#_8-handover-summary" aria-label="Permalink to &quot;8. Handover Summary&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Main question and acceptance standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Most reliable evidence:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Least reliable or still missing evidence:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Repeated errors/risks:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task and stop condition:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence folder or link:</span></span></code></pre></div><p>When handing this summary to your future self, a peer, or AI, ask them to work only from this record. They should not pretend to remember another session or fill in facts that are not present.</p><p>Related chapters: <a href="./../threads/part-3/5-evidence-and-transfer">Evidence: How Change Becomes Visible</a> | <a href="./toolkit">Toolkit Overview</a> | <a href="./rhythm-ledger">Rhythm Ledger</a> | <a href="./../reference/glossary">Glossary of Terms and Methods</a></p>`,32)])])}const m=a(i,[["render",o]]);export{k as __pageData,m as default};
